from pathlib import Path
import shutil, py_compile, sys
p=Path(sys.argv[1] if len(sys.argv)>1 else 'app.py')
if not p.exists(): raise SystemExit(f'Missing {p}')
marker='# ==================== BILLING CONTROL + INVOICE CONSISTENCY V18 ===================='
s=p.read_text(encoding='utf-8')
if marker in s: print('Billing audit V18 already installed.'); raise SystemExit(0)
bak=p.with_name(p.name+'.before_billing_audit_v18.bak');shutil.copy2(p,bak)
PATCH='\n\n# ==================== BILLING CONTROL + INVOICE CONSISTENCY V18 ====================\nimport json as _json_v18\nfrom decimal import Decimal as _Decimal_v18\n\nclass EntryStateV18(db.Model):\n    __tablename__=\'entry_state_v18\'\n    id=db.Column(db.Integer,primary_key=True)\n    timer_id=db.Column(db.Integer,db.ForeignKey(\'timer.id\',ondelete=\'CASCADE\'),unique=True,nullable=False,index=True)\n    active=db.Column(db.Boolean,nullable=False,default=True)\n    reason=db.Column(db.Text)\n    changed_by=db.Column(db.Integer,db.ForeignKey(\'user.id\'))\n    changed_at=db.Column(db.DateTime(timezone=True),default=lambda:datetime.now(timezone.utc),nullable=False)\n\nclass BillingAuditV18(db.Model):\n    __tablename__=\'billing_audit_v18\'\n    id=db.Column(db.Integer,primary_key=True)\n    entity_type=db.Column(db.String(50),nullable=False,index=True)\n    entity_id=db.Column(db.Integer,nullable=False,index=True)\n    action=db.Column(db.String(80),nullable=False)\n    user_id=db.Column(db.Integer,db.ForeignKey(\'user.id\'))\n    before_json=db.Column(db.Text);after_json=db.Column(db.Text)\n    created_at=db.Column(db.DateTime(timezone=True),default=lambda:datetime.now(timezone.utc),nullable=False)\n\nclass TimerInvoiceLinkV18(db.Model):\n    __tablename__=\'timer_invoice_link_v13\';__table_args__={\'extend_existing\':True}\n    id=db.Column(db.Integer,primary_key=True)\n    timer_id=db.Column(db.Integer,db.ForeignKey(\'timer.id\'),nullable=False,index=True)\n    draft_id=db.Column(db.Integer,db.ForeignKey(\'fee_note_draft_v2.id\'),index=True)\n    invoice_number=db.Column(db.String(255),nullable=False,index=True)\n    issued_at=db.Column(db.DateTime(timezone=True),nullable=False)\n\nwith app.app_context(): db.create_all()\n\ndef _v18_num(v,default=0.0):\n    try:return float(v)\n    except (TypeError,ValueError):return default\n\ndef _v18_money(v):return round(_v18_num(v),2)\n\ndef _v18_dump(v):\n    return _json_v18.dumps(v,default=lambda x:str(x) if isinstance(x,(_Decimal_v18,datetime,date)) else x,ensure_ascii=False)\n\ndef _v18_entry_snap(t):\n    return {\'id\':t.id,\'user_id\':t.user_id,\'client_id\':t.client_id,\'matter_id\':t.matter_id,\'service_date\':t.start_time.isoformat() if t.start_time else None,\'services\':t.services,\'worked_hours\':t.worked_hours,\'billable_hours\':t.billable_hours,\'rate\':str(t.applied_rate or 0),\'amount\':str(t.amount or 0),\'status\':t.invoiced_status,\'invoice_number\':t.invoice_number}\n\ndef _v18_draft_snap(d):\n    return {\'id\':d.id,\'invoice_number\':d.invoice_number,\'status\':d.status,\'client_id\':d.client_id,\'matter_id\':d.matter_id,\'billing_name\':d.billing_name,\'billing_address\':d.billing_address,\'net\':str(d.net_total or 0),\'vat\':str(d.vat_amount or 0),\'gross\':str(d.gross_total or 0)}\n\ndef _v18_audit(kind,eid,action,before=None,after=None):\n    db.session.add(BillingAuditV18(entity_type=kind,entity_id=eid,action=action,user_id=session.get(\'uid\'),before_json=_v18_dump(before) if before is not None else None,after_json=_v18_dump(after) if after is not None else None))\n\ndef _v18_state(timer_id,create=False):\n    s=EntryStateV18.query.filter_by(timer_id=timer_id).first()\n    if not s and create:s=EntryStateV18(timer_id=timer_id,active=True);db.session.add(s)\n    return s\n\ndef _v18_active(timer_id):\n    s=_v18_state(timer_id);return True if s is None else bool(s.active)\n\ndef _v18_recalc(d):\n    net=sum(_v18_num(x.amount) for x in FeeNoteLine.query.filter_by(draft_id=d.id,included=True).all())\n    if d.show_telecom:net+=_v18_num(d.telecom_amount)\n    reverse=d.vat_treatment in (\'Reverse charge\',\'Other exemption\')\n    d.vat_rate=0 if reverse else (_v18_num(d.vat_rate,19) or 19)\n    d.net_total=_v18_money(net);d.vat_amount=_v18_money(net*d.vat_rate/100);d.gross_total=_v18_money(d.net_total+d.vat_amount)\n\ndef _v18_sync_master(d,force=False):\n    c=db.session.get(Client,d.client_id);m=db.session.get(Matter,d.matter_id) if d.matter_id else None;ct=db.session.get(Contact,d.contact_id) if d.contact_id else None\n    if not c or (not force and d.status in (\'Issued\',\'Cancelled\')):return\n    d.client_name=c.name;d.billing_name=c.billing_name or c.name;d.billing_address=c.address or \'\';d.country=c.country or \'\';d.vat_number=c.vat_number or \'\'\n    d.currency=(m.currency if m and m.currency else None) or c.currency or \'EUR\';d.payment_terms=(m.payment_terms if m and m.payment_terms else None) or c.payment_terms or \'\'\n    d.vat_treatment=(m.vat_treatment if m and m.vat_treatment else None) or c.vat_treatment or \'Standard VAT\';d.language=(m.language if m and m.language else None) or c.language or \'English\';d.matter_text=m.name if m else (d.matter_text or \'\')\n    if ct:d.contact_name=ct.display_name\n\ndef _v18_links(timer_id):return TimerInvoiceLinkV18.query.filter_by(timer_id=timer_id).all()\n\ndef _v18_refresh_timer(t):\n    nums=[]\n    for l in _v18_links(t.id):\n        if l.invoice_number and l.invoice_number not in nums:nums.append(l.invoice_number)\n    t.invoice_number=\' | \'.join(nums) if nums else None;t.invoiced_status=\'Invoiced\' if nums else \'Unbilled\'\n\ndef _v18_sync_links(d):\n    old=TimerInvoiceLinkV18.query.filter_by(draft_id=d.id).all();by_timer={x.timer_id:x for x in old}\n    included={x.source_timer_id for x in FeeNoteLine.query.filter_by(draft_id=d.id,included=True).all() if x.source_timer_id};affected=set(by_timer)|included\n    if d.status==\'Issued\' and d.invoice_number:\n        for tid in included:\n            if tid not in by_timer:db.session.add(TimerInvoiceLinkV18(timer_id=tid,draft_id=d.id,invoice_number=d.invoice_number,issued_at=d.issued_at or datetime.now(timezone.utc)))\n            else:by_timer[tid].invoice_number=d.invoice_number\n        for tid,l in by_timer.items():\n            if tid not in included:db.session.delete(l)\n    else:\n        for l in old:db.session.delete(l)\n    db.session.flush()\n    for tid in affected:\n        t=db.session.get(Timer,tid)\n        if t:_v18_refresh_timer(t)\n\ndef _v18_issued_dependency(tid):\n    if _v18_links(tid):return True\n    for line in FeeNoteLine.query.filter_by(source_timer_id=tid).all():\n        d=db.session.get(FeeNoteDraft,line.draft_id)\n        if d and d.status==\'Issued\':return True\n    return False\n\ndef _v18_sync_draft_lines(t):\n    for line in FeeNoteLine.query.filter_by(source_timer_id=t.id).all():\n        d=db.session.get(FeeNoteDraft,line.draft_id)\n        if not d or d.status in (\'Issued\',\'Cancelled\'):continue\n        line.service_date=t.start_time.date().isoformat();line.description=t.services or \'\';line.quantity=_v18_num(t.billable_hours);line.rate=_v18_num(t.applied_rate);line.timekeeper=t.user.display_name if t.user else line.timekeeper\n        if not line.amount_override:line.amount=_v18_money(line.quantity*_v18_num(line.rate))\n        _v18_recalc(d)\n\n# Preserve line breaks from the client billing address in generated Word files.\nif \'previous\' in globals() and hasattr(previous,\'replace_in_paragraph\'):\n    def _v18_replace_paragraph(p,replacements):\n        original=\'\'.join(r.text for r in p.runs);changed=original\n        for old,new in replacements.items():changed=changed.replace(old,str(new or \'\'))\n        if changed==original:return\n        run=p.runs[0] if p.runs else p.add_run();run.text=\'\'\n        for i,line in enumerate(changed.replace(\'\\r\\n\',\'\\n\').replace(\'\\r\',\'\\n\').split(\'\\n\')):\n            if i:run.add_break()\n            run.add_text(line)\n        for extra in p.runs[1:]:extra.text=\'\'\n    previous.replace_in_paragraph=_v18_replace_paragraph\n\nBILLING_CONTROL_V18=r\'\'\'{% extends "base.html" %}{% block content %}\n<h1>Administrator billing control</h1><p>Add, edit, deactivate, reactivate, safely delete and restore entries. Only active rows are included in active totals and new invoices.</p>\n<section class="card"><form method="get"><div class="grid"><label>User<select name="user_id"><option value="">All</option>{% for u in users %}<option value="{{u.id}}" {% if selected_user==u.id %}selected{% endif %}>{{u.display_name}}</option>{% endfor %}</select></label><label>Client<select id="bc-client" name="client_id"><option value="">All</option>{% for c in clients %}<option value="{{c.id}}" {% if selected_client==c.id %}selected{% endif %}>{{c.name}}</option>{% endfor %}</select></label><label>Matter<select id="bc-matter" name="matter_id"><option value="">All</option>{% for m in matters %}<option value="{{m.id}}" data-client="{{m.client_id}}" {% if selected_matter==m.id %}selected{% endif %}>{{m.name}}</option>{% endfor %}</select></label><label>From<input type="date" name="date_from" value="{{date_from}}"></label><label>To<input type="date" name="date_to" value="{{date_to}}"></label><label>Billing<select name="billing"><option value="">All</option><option value="unbilled" {% if billing==\'unbilled\' %}selected{% endif %}>Unbilled</option><option value="billed" {% if billing==\'billed\' %}selected{% endif %}>Billed</option></select></label><label>State<select name="state"><option value="active" {% if state==\'active\' %}selected{% endif %}>Active</option><option value="inactive" {% if state==\'inactive\' %}selected{% endif %}>Deactivated</option><option value="all" {% if state==\'all\' %}selected{% endif %}>All</option></select></label></div><button>Apply filters</button></form><p><b>Active totals:</b> {{\'%.4f\'|format(total_worked)}} worked h | {{\'%.4f\'|format(total_billable)}} billable h | {{\'%.2f\'|format(total_amount)}} EUR</p><p><b>Deactivated amount excluded:</b> {{\'%.2f\'|format(inactive_amount)}} EUR</p></section>\n<section class="card"><h2>Add entry for an employee</h2><form method="post" action="{{url_for(\'billing_entry_add_v18\')}}"><div class="grid"><label>User<select name="user_id" required>{% for u in users %}<option value="{{u.id}}">{{u.display_name}}</option>{% endfor %}</select></label><label>Client<select id="add-client" name="client_id" required><option value="">Select</option>{% for c in clients %}<option value="{{c.id}}">{{c.name}}</option>{% endfor %}</select></label><label>Matter<select id="add-matter" name="matter_id" required><option value="">Select client first</option></select></label><label>Service date<input type="date" name="service_date" value="{{today}}" required></label><label>Worked hours<input type="number" min="0" step="0.0001" name="worked_hours" required></label><label>Billable hours<input type="number" min="0" step="0.0001" name="billable_hours" required></label><label>Hourly rate<input type="number" min="0" step="0.01" name="rate"></label></div><label>Service description<textarea name="services" required></textarea></label><label>Notes<textarea name="notes"></textarea></label><button>Add entry</button></form></section>\n<section class="card wide table-scroll"><table class="v18-wide"><tr><th>Date</th><th>User</th><th>Client</th><th>Matter</th><th>Service description</th><th>Worked</th><th>Billable</th><th>Rate</th><th>Amount</th><th>Status</th><th>Actions</th></tr>{% for t in entries %}<tr class="{% if not active_map[t.id] %}v18-inactive{% endif %}"><form method="post" action="{{url_for(\'billing_entry_save_v18\',timer_id=t.id)}}"><td><input type="date" name="service_date" value="{{t.start_time.strftime(\'%Y-%m-%d\')}}"></td><td>{{user_names.get(t.user_id,\'\')}}</td><td>{{client_names.get(t.client_id,\'\')}}</td><td class="v18-matter">{{matter_names.get(t.matter_id,\'\')}}</td><td class="v18-services"><textarea name="services">{{t.services or \'\'}}</textarea></td><td><input type="number" step="0.0001" min="0" name="worked_hours" value="{{t.worked_hours or 0}}"></td><td><input type="number" step="0.0001" min="0" name="billable_hours" value="{{t.billable_hours or 0}}"></td><td><input type="number" step="0.01" min="0" name="rate" value="{{t.applied_rate or 0}}"></td><td><input type="number" step="0.01" min="0" name="amount" value="{{t.amount or 0}}"></td><td>{{\'Active\' if active_map[t.id] else \'Deactivated\'}}<br>{{t.invoice_number or \'Unbilled\'}}</td><td><button>Save</button></form><form method="post" action="{{url_for(\'billing_entry_action_v18\',timer_id=t.id)}}">{% if active_map[t.id] %}<button name="action" value="deactivate" class="secondary">Deactivate</button>{% else %}<button name="action" value="reactivate" class="secondary">Reactivate</button>{% endif %}<button name="action" value="unbill" class="secondary">Restore unbilled</button><button name="action" value="delete" class="danger" onclick="return confirm(\'Delete if no issued invoice depends on it?\')">Delete</button></form></td></tr>{% else %}<tr><td colspan="11">No entries.</td></tr>{% endfor %}</table></section>\n<script>async function loadM(c,sid){let s=document.getElementById(sid);if(!c){s.innerHTML=\'<option value="">Select client first</option>\';return}let r=await fetch(\'/admin/billing-control-v18/matters/\'+c),d=await r.json();s.innerHTML=\'<option value="">Select</option>\'+d.map(m=>`<option value="${m.id}">${m.reference||\'\'} | ${m.name}</option>`).join(\'\')}document.getElementById(\'add-client\').onchange=e=>loadM(e.target.value,\'add-matter\');const fc=document.getElementById(\'bc-client\'),fm=document.getElementById(\'bc-matter\');function filt(){let c=fc.value;Array.from(fm.options).forEach(o=>{if(o.value)o.hidden=!!c&&o.dataset.client!==c});if(fm.selectedOptions[0]&&fm.selectedOptions[0].hidden)fm.value=\'\'}fc.onchange=filt;filt();</script>\n{% endblock %}\'\'\'\n\n@app.get(\'/admin/billing-control-v18\')\n@login_required\n@admin_required\ndef billing_control_v18():\n    q=Timer.query;su=request.args.get(\'user_id\',type=int);sc=request.args.get(\'client_id\',type=int);sm=request.args.get(\'matter_id\',type=int);df=(request.args.get(\'date_from\') or \'\').strip();dt=(request.args.get(\'date_to\') or \'\').strip();billing=(request.args.get(\'billing\') or \'\').strip();state=(request.args.get(\'state\') or \'active\').strip()\n    if su:q=q.filter(Timer.user_id==su)\n    if sc:q=q.filter(Timer.client_id==sc)\n    if sm:q=q.filter(Timer.matter_id==sm)\n    try:\n        if df:q=q.filter(Timer.start_time>=datetime.strptime(df,\'%Y-%m-%d\').replace(tzinfo=timezone.utc))\n        if dt:q=q.filter(Timer.start_time<datetime.strptime(dt,\'%Y-%m-%d\').replace(tzinfo=timezone.utc)+timedelta(days=1))\n    except ValueError:flash(\'Use valid dates.\')\n    if billing==\'unbilled\':q=q.filter(db.or_(Timer.invoiced_status!=\'Invoiced\',Timer.invoiced_status.is_(None)))\n    if billing==\'billed\':q=q.filter(Timer.invoiced_status==\'Invoiced\')\n    candidates=q.order_by(Timer.start_time.desc(),Timer.id.desc()).all();am={t.id:_v18_active(t.id) for t in candidates}\n    entries=[t for t in candidates if state==\'all\' or (state==\'active\' and am[t.id]) or (state==\'inactive\' and not am[t.id])];active=[t for t in entries if am[t.id]];inactive=[t for t in entries if not am[t.id]]\n    users=User.query.order_by(User.display_name).all();clients=Client.query.order_by(db.func.lower(Client.name),Client.id).all();matters=Matter.query.order_by(db.func.lower(Matter.name),Matter.id).all()\n    return render_template_string(BILLING_CONTROL_V18,entries=entries,users=users,clients=clients,matters=matters,selected_user=su,selected_client=sc,selected_matter=sm,date_from=df,date_to=dt,billing=billing,state=state,active_map=am,user_names={u.id:u.display_name for u in users},client_names={c.id:c.name for c in clients},matter_names={m.id:m.name for m in matters},total_worked=sum(_v18_num(t.worked_hours) for t in active),total_billable=sum(_v18_num(t.billable_hours) for t in active),total_amount=sum(_v18_num(t.amount) for t in active),inactive_amount=sum(_v18_num(t.amount) for t in inactive),today=date.today().isoformat())\n\n@app.get(\'/admin/billing-control-v18/matters/<int:client_id>\')\n@login_required\n@admin_required\ndef billing_matters_v18(client_id):return jsonify([{\'id\':m.id,\'reference\':m.reference,\'name\':m.name} for m in Matter.query.filter_by(client_id=client_id).order_by(db.func.lower(Matter.name),Matter.id).all()])\n\n@app.post(\'/admin/billing-control-v18/add\')\n@login_required\n@admin_required\ndef billing_entry_add_v18():\n    u=db.session.get(User,int(request.form[\'user_id\']));c=db.session.get(Client,int(request.form[\'client_id\']));m=db.session.get(Matter,int(request.form[\'matter_id\']))\n    if not u or not c or not m or m.client_id!=c.id:flash(\'Invalid user/client/matter.\');return redirect(url_for(\'billing_control_v18\'))\n    start=datetime.strptime(request.form[\'service_date\'],\'%Y-%m-%d\').replace(tzinfo=timezone.utc);worked=max(0,_v18_num(request.form.get(\'worked_hours\')));bill=max(0,_v18_num(request.form.get(\'billable_hours\')));rate=_v18_num(request.form.get(\'rate\'),None)\n    if rate is None:rate=_v18_num(m.matter_hourly_rate,_v18_num(c.client_hourly_rate,_v18_num(u.default_hourly_rate)))\n    t=Timer(user_id=u.id,client_id=c.id,matter_id=m.id,services=(request.form.get(\'services\') or \'\').strip(),notes=(request.form.get(\'notes\') or \'\').strip(),start_time=start,stop_time=start+timedelta(hours=worked),status=\'Stopped\',paused_seconds=0,worked_hours=worked,billable_hours=bill,timekeeper_rate=u.default_hourly_rate,client_rate=c.client_hourly_rate,matter_rate=m.matter_hourly_rate,applied_rate=rate,billable=True,amount=_v18_money(bill*rate),invoiced_status=\'Unbilled\')\n    db.session.add(t);db.session.flush();_v18_state(t.id,True);_v18_audit(\'timer\',t.id,\'create\',None,_v18_entry_snap(t));db.session.commit();flash(\'Entry added.\');return redirect(url_for(\'billing_control_v18\'))\n\n@app.post(\'/admin/billing-control-v18/<int:timer_id>/save\')\n@login_required\n@admin_required\ndef billing_entry_save_v18(timer_id):\n    t=db.session.get(Timer,timer_id)\n    if not t:return (\'Not found\',404)\n    before=_v18_entry_snap(t);d=datetime.strptime(request.form[\'service_date\'],\'%Y-%m-%d\').date();tm=t.start_time.timetz();t.start_time=datetime.combine(d,tm)\n    if t.start_time.tzinfo is None:t.start_time=t.start_time.replace(tzinfo=timezone.utc)\n    t.services=(request.form.get(\'services\') or \'\').strip();t.worked_hours=max(0,_v18_num(request.form.get(\'worked_hours\')));t.billable_hours=max(0,_v18_num(request.form.get(\'billable_hours\')));t.applied_rate=max(0,_v18_num(request.form.get(\'rate\')));amount=(request.form.get(\'amount\') or \'\').strip();t.amount=_v18_money(amount) if amount else _v18_money(t.billable_hours*t.applied_rate)\n    if t.stop_time:t.stop_time=t.start_time+timedelta(hours=t.worked_hours)\n    _v18_sync_draft_lines(t);_v18_audit(\'timer\',t.id,\'edit\',before,_v18_entry_snap(t));db.session.commit();flash(\'Entry and editable invoice drafts updated.\');return redirect(request.referrer or url_for(\'billing_control_v18\'))\n\n@app.post(\'/admin/billing-control-v18/<int:timer_id>/action\')\n@login_required\n@admin_required\ndef billing_entry_action_v18(timer_id):\n    t=db.session.get(Timer,timer_id)\n    if not t:return (\'Not found\',404)\n    action=request.form.get(\'action\');before=_v18_entry_snap(t);s=_v18_state(t.id,True)\n    if action==\'deactivate\':s.active=False;s.changed_by=session.get(\'uid\');s.changed_at=datetime.now(timezone.utc);flash(\'Entry deactivated and excluded.\')\n    elif action==\'reactivate\':s.active=True;s.changed_by=session.get(\'uid\');s.changed_at=datetime.now(timezone.utc);flash(\'Entry reactivated.\')\n    elif action==\'unbill\':\n        if _v18_issued_dependency(t.id):flash(\'Issued invoice dependency remains. Cancel/revise that invoice first.\');return redirect(request.referrer or url_for(\'billing_control_v18\'))\n        drafts=set()\n        for line in FeeNoteLine.query.filter_by(source_timer_id=t.id).all():drafts.add(line.draft_id);db.session.delete(line)\n        for link in _v18_links(t.id):db.session.delete(link)\n        db.session.flush();t.invoice_number=None;t.invoiced_status=\'Unbilled\'\n        for did in drafts:\n            d=db.session.get(FeeNoteDraft,did)\n            if d:_v18_recalc(d)\n        flash(\'Entry restored to unbilled.\')\n    elif action==\'delete\':\n        if _v18_issued_dependency(t.id):flash(\'Cannot delete an entry used by an issued invoice.\');return redirect(request.referrer or url_for(\'billing_control_v18\'))\n        for line in FeeNoteLine.query.filter_by(source_timer_id=t.id).all():db.session.delete(line)\n        for link in _v18_links(t.id):db.session.delete(link)\n        _v18_audit(\'timer\',t.id,\'delete\',before,None);db.session.delete(t);db.session.commit();flash(\'Entry deleted.\');return redirect(url_for(\'billing_control_v18\'))\n    _v18_audit(\'timer\',t.id,action,before,_v18_entry_snap(t));db.session.commit();return redirect(request.referrer or url_for(\'billing_control_v18\'))\n\nREGISTER_V18=r\'\'\'{% extends "base.html" %}{% block content %}<h1>Invoice register</h1><p>Live values from the same invoice records used for Word generation.</p><section class="card wide table-scroll"><table><tr><th>Number</th><th>Status</th><th>Client</th><th>Matter</th><th>Date</th><th>Net</th><th>VAT</th><th>Gross</th><th></th></tr>{% for d in drafts %}<tr><td>{{d.invoice_number or (\'Draft \'+d.id|string)}}</td><td>{{d.status}}</td><td>{{d.client_name}}</td><td class="v18-matter">{{d.matter_text}}</td><td>{{d.document_date}}</td><td>{{d.net_total}}</td><td>{{d.vat_amount}}</td><td>{{d.gross_total}}</td><td><a href="{{url_for(\'invoice_control_edit_v18\',draft_id=d.id)}}">Edit/reconcile</a></td></tr>{% endfor %}</table></section>{% endblock %}\'\'\'\n\n@app.get(\'/admin/invoice-control-v18\')\n@login_required\n@admin_required\ndef invoice_control_register_v18():return render_template_string(REGISTER_V18,drafts=FeeNoteDraft.query.order_by(FeeNoteDraft.id.desc()).all())\n\nEDITOR_V18=r\'\'\'{% extends "base.html" %}{% block content %}<h1>Invoice {{draft.invoice_number or (\'Draft \'+draft.id|string)}}</h1><p><a href="{{url_for(\'invoice_control_register_v18\')}}">Register</a> | <a href="{{url_for(\'edit_fee_note\',draft_id=draft.id)}}">Open existing full editor</a></p><section class="card"><form method="post"><div class="grid"><label>Status<select name="status">{% for x in [\'Draft\',\'Issued\',\'Cancelled\'] %}<option {% if draft.status==x %}selected{% endif %}>{{x}}</option>{% endfor %}</select></label><label>Invoice number<input name="invoice_number" value="{{draft.invoice_number or \'\'}}"></label><label>Client<select id="inv-client" name="client_id">{% for c in clients %}<option value="{{c.id}}" {% if draft.client_id==c.id %}selected{% endif %}>{{c.name}}</option>{% endfor %}</select></label><label>Matter<select id="inv-matter" name="matter_id"><option value="">No matter</option>{% for m in matters %}<option value="{{m.id}}" {% if draft.matter_id==m.id %}selected{% endif %}>{{m.name}}</option>{% endfor %}</select></label><label>Billing name<input name="billing_name" value="{{draft.billing_name or \'\'}}"></label><label>Billing address<textarea name="billing_address">{{draft.billing_address or \'\'}}</textarea></label><label>Country<input name="country" value="{{draft.country or \'\'}}"></label><label>Contact<input name="contact_name" value="{{draft.contact_name or \'\'}}"></label><label>Document date<input name="document_date" value="{{draft.document_date or \'\'}}"></label><label>Payment terms<input name="payment_terms" value="{{draft.payment_terms or \'\'}}"></label><label>Currency<input name="currency" value="{{draft.currency or \'EUR\'}}"></label><label>VAT treatment<select name="vat_treatment">{% for x in [\'Standard VAT\',\'Reverse charge\',\'Other exemption\'] %}<option {% if draft.vat_treatment==x %}selected{% endif %}>{{x}}</option>{% endfor %}</select></label><label>VAT rate<input type="number" step="0.01" name="vat_rate" value="{{draft.vat_rate if draft.vat_rate is not none else 19}}"></label><label>Telecom amount<input type="number" step="0.01" name="telecom_amount" value="{{draft.telecom_amount or 0}}"></label></div><label class="check"><input type="checkbox" name="show_telecom" {% if draft.show_telecom %}checked{% endif %}> Include telecommunications</label><button>Save and recalculate register</button><button name="refresh_master" value="1" class="secondary">Refresh client/matter details</button></form><p><b>Totals:</b> Net {{draft.net_total}} | VAT {{draft.vat_amount}} | Gross {{draft.gross_total}} {{draft.currency}}</p></section>\n<section class="card wide table-scroll"><form method="post"><input type="hidden" name="save_lines" value="1"><table><tr><th>Include</th><th>Date</th><th>Type</th><th>Description</th><th>Timekeeper</th><th>Hours/Qty</th><th>Rate</th><th>Amount</th><th>Sync entry</th></tr>{% for l in lines %}<tr><td><input type="checkbox" name="included_{{l.id}}" {% if l.included %}checked{% endif %}></td><td><input type="date" name="date_{{l.id}}" value="{{l.service_date or \'\'}}"></td><td><input name="type_{{l.id}}" value="{{l.line_type or \'\'}}"></td><td class="v18-services"><textarea name="description_{{l.id}}">{{l.description or \'\'}}</textarea></td><td><input name="timekeeper_{{l.id}}" value="{{l.timekeeper or \'\'}}"></td><td><input type="number" step="0.0001" min="0" name="quantity_{{l.id}}" value="{{l.quantity or 0}}"></td><td><input type="number" step="0.01" min="0" name="rate_{{l.id}}" value="{{l.rate or 0}}"></td><td><input type="number" step="0.01" min="0" name="amount_{{l.id}}" value="{{l.amount or 0}}"></td><td>{% if l.source_timer_id %}<input type="checkbox" name="sync_{{l.id}}" checked>{% else %}Free line{% endif %}</td></tr>{% endfor %}</table><button>Save lines and recalculate</button></form><h3>Add dated line</h3><form method="post" action="{{url_for(\'invoice_line_add_v18\',draft_id=draft.id)}}"><div class="grid"><label>Date<input type="date" name="service_date" required></label><label>Type<input name="line_type" value="Time-based fees"></label><label>Timekeeper<input name="timekeeper"></label><label>Hours/Qty<input type="number" min="0" step="0.0001" name="quantity" required></label><label>Rate<input type="number" min="0" step="0.01" name="rate" required></label></div><label>Description<textarea name="description" required></textarea></label><button>Add line and calculate</button></form></section>\n<section class="card"><form method="post" action="{{url_for(\'invoice_control_action_v18\',draft_id=draft.id)}}"><button name="action" value="cancel" class="danger" onclick="return confirm(\'Cancel invoice and release linked entries?\')">Cancel and release entries</button>{% if draft.status==\'Cancelled\' %}<button name="action" value="reactivate" class="secondary">Reactivate draft</button>{% endif %}</form>{% if draft.status!=\'Cancelled\' %}<form method="post" action="{{url_for(\'issue_fee_note\',draft_id=draft.id)}}"><button>{{\'Regenerate Word invoice\' if draft.invoice_number else \'Issue and download Word invoice\'}}</button></form>{% endif %}</section><script>async function ms(){let c=document.getElementById(\'inv-client\').value,s=document.getElementById(\'inv-matter\'),cur=\'{{draft.matter_id or \'\'}}\',r=await fetch(\'/admin/billing-control-v18/matters/\'+c),d=await r.json();s.innerHTML=\'<option value="">No matter</option>\'+d.map(m=>`<option value="${m.id}" ${String(m.id)===String(cur)?\'selected\':\'\'}>${m.reference||\'\'} | ${m.name}</option>`).join(\'\')}document.getElementById(\'inv-client\').onchange=ms;</script>{% endblock %}\'\'\'\n\n@app.route(\'/admin/invoice-control-v18/<int:draft_id>\',methods=[\'GET\',\'POST\'])\n@login_required\n@admin_required\ndef invoice_control_edit_v18(draft_id):\n    d=db.session.get(FeeNoteDraft,draft_id)\n    if not d:return (\'Not found\',404)\n    if request.method==\'POST\':\n        before=_v18_draft_snap(d)\n        if request.form.get(\'save_lines\'):\n            for l in FeeNoteLine.query.filter_by(draft_id=d.id).all():\n                l.included=f\'included_{l.id}\' in request.form;l.service_date=(request.form.get(f\'date_{l.id}\') or \'\').strip();l.line_type=(request.form.get(f\'type_{l.id}\') or \'Free data entry\').strip();l.description=(request.form.get(f\'description_{l.id}\') or \'\').strip();l.timekeeper=(request.form.get(f\'timekeeper_{l.id}\') or \'\').strip();l.quantity=max(0,_v18_num(request.form.get(f\'quantity_{l.id}\')));l.rate=max(0,_v18_num(request.form.get(f\'rate_{l.id}\')));entered=(request.form.get(f\'amount_{l.id}\') or \'\').strip();calc=_v18_money(l.quantity*l.rate);l.amount=_v18_money(entered) if entered else calc;l.amount_override=bool(entered and abs(_v18_num(l.amount)-calc)>.001)\n                if l.source_timer_id and f\'sync_{l.id}\' in request.form:\n                    t=db.session.get(Timer,l.source_timer_id)\n                    if t:\n                        t.services=l.description;t.billable_hours=l.quantity;t.applied_rate=l.rate;t.amount=l.amount\n                        if l.service_date:\n                            nd=datetime.strptime(l.service_date,\'%Y-%m-%d\').date();tm=t.start_time.timetz();t.start_time=datetime.combine(nd,tm)\n                            if t.start_time.tzinfo is None:t.start_time=t.start_time.replace(tzinfo=timezone.utc)\n        else:\n            d.status=(request.form.get(\'status\') or d.status).strip();d.invoice_number=(request.form.get(\'invoice_number\') or \'\').strip() or None;d.client_id=int(request.form[\'client_id\']);d.matter_id=int(request.form[\'matter_id\']) if request.form.get(\'matter_id\') else None;d.billing_name=(request.form.get(\'billing_name\') or \'\').strip();d.billing_address=(request.form.get(\'billing_address\') or \'\').strip();d.country=(request.form.get(\'country\') or \'\').strip();d.contact_name=(request.form.get(\'contact_name\') or \'\').strip();d.document_date=(request.form.get(\'document_date\') or \'\').strip();d.payment_terms=(request.form.get(\'payment_terms\') or \'\').strip();d.currency=(request.form.get(\'currency\') or \'EUR\').strip();d.vat_treatment=(request.form.get(\'vat_treatment\') or \'Standard VAT\').strip();d.vat_rate=_v18_num(request.form.get(\'vat_rate\'),19);d.telecom_amount=_v18_money(request.form.get(\'telecom_amount\'));d.show_telecom=\'show_telecom\' in request.form\n            _v18_sync_master(d,force=bool(request.form.get(\'refresh_master\')))\n        _v18_recalc(d);_v18_sync_links(d);_v18_audit(\'invoice\',d.id,\'edit\',before,_v18_draft_snap(d));db.session.commit();flash(\'Invoice and register updated.\');return redirect(url_for(\'invoice_control_edit_v18\',draft_id=d.id))\n    clients=Client.query.order_by(db.func.lower(Client.name),Client.id).all();matters=Matter.query.filter_by(client_id=d.client_id).order_by(db.func.lower(Matter.name),Matter.id).all();lines=FeeNoteLine.query.filter_by(draft_id=d.id).order_by(FeeNoteLine.sort_order,FeeNoteLine.id).all();return render_template_string(EDITOR_V18,draft=d,clients=clients,matters=matters,lines=lines)\n\n@app.post(\'/admin/invoice-control-v18/<int:draft_id>/line/add\')\n@login_required\n@admin_required\ndef invoice_line_add_v18(draft_id):\n    d=db.session.get(FeeNoteDraft,draft_id)\n    if not d:return (\'Not found\',404)\n    q=max(0,_v18_num(request.form.get(\'quantity\')));r=max(0,_v18_num(request.form.get(\'rate\')));order=db.session.query(db.func.max(FeeNoteLine.sort_order)).filter(FeeNoteLine.draft_id==d.id).scalar() or 0;l=FeeNoteLine(draft_id=d.id,sort_order=order+1,included=True,line_type=(request.form.get(\'line_type\') or \'Time-based fees\').strip(),description=(request.form.get(\'description\') or \'\').strip(),service_date=(request.form.get(\'service_date\') or \'\').strip(),timekeeper=(request.form.get(\'timekeeper\') or \'\').strip(),quantity=q,rate=r,amount=_v18_money(q*r),amount_override=False,include_in_detail=True);db.session.add(l);db.session.flush();_v18_recalc(d);_v18_audit(\'invoice_line\',l.id,\'create\',None,{\'draft_id\':d.id,\'amount\':str(l.amount)});db.session.commit();flash(\'Line added and totals recalculated.\');return redirect(url_for(\'invoice_control_edit_v18\',draft_id=d.id))\n\n@app.post(\'/admin/invoice-control-v18/<int:draft_id>/action\')\n@login_required\n@admin_required\ndef invoice_control_action_v18(draft_id):\n    d=db.session.get(FeeNoteDraft,draft_id)\n    if not d:return (\'Not found\',404)\n    before=_v18_draft_snap(d);action=request.form.get(\'action\')\n    if action==\'cancel\':d.status=\'Cancelled\';_v18_sync_links(d);flash(\'Invoice cancelled; historical draft retained and entries released where safe.\')\n    elif action==\'reactivate\':d.status=\'Draft\';_v18_sync_links(d);flash(\'Draft reactivated.\')\n    _v18_audit(\'invoice\',d.id,action,before,_v18_draft_snap(d));db.session.commit();return redirect(url_for(\'invoice_control_edit_v18\',draft_id=d.id))\n\n_old_issue_v18=app.view_functions.get(\'issue_fee_note\')\nif _old_issue_v18:\n    def issue_synced_v18(draft_id):\n        response=_old_issue_v18(draft_id);d=db.session.get(FeeNoteDraft,draft_id)\n        if d and d.status==\'Issued\':_v18_sync_links(d);_v18_audit(\'invoice\',d.id,\'issue_or_regenerate\',None,_v18_draft_snap(d));db.session.commit()\n        return response\n    app.view_functions[\'issue_fee_note\']=issue_synced_v18\n\n_old_context_v18=app.view_functions.get(\'invoice_context\')\nif _old_context_v18:\n    def invoice_context_active_v18(client_id):\n        response=_old_context_v18(client_id)\n        try:data=response.get_json();data[\'timers\']=[x for x in data.get(\'timers\',[]) if _v18_active(x.get(\'id\'))];return jsonify(data)\n        except Exception:return response\n    app.view_functions[\'invoice_context\']=invoice_context_active_v18\n\nif \'invoice_register_v5\' in app.view_functions:app.view_functions[\'invoice_register_v5\']=login_required(admin_required(invoice_control_register_v18))\n\n@app.after_request\ndef billing_layout_v18(response):\n    if response.status_code==200 and \'text/html\' in response.headers.get(\'Content-Type\',\'\'):\n        html=response.get_data(as_text=True)\n        if request.endpoint==\'admin\' and \'/admin/billing-control-v18\' not in html:\n            block=\'<section class="card"><h2>Billing control</h2><p><a href="/admin/billing-control-v18">Manage all entries and totals</a> | <a href="/admin/invoice-control-v18">Synchronized invoice register</a></p></section>\';html=html.replace(\'</main>\',block+\'</main>\') if \'</main>\' in html else html+block\n        if \'billing-layout-v18\' not in html:\n            css=\'\'\'<style id="billing-layout-v18">html,body{max-width:100%;overflow-x:auto!important}.card.wide,.table-scroll{display:block;max-width:100%;overflow-x:auto!important;-webkit-overflow-scrolling:touch}.v18-wide{width:max-content;min-width:100%}.v18-matter{width:190px;min-width:160px;max-width:190px;white-space:normal!important;word-break:normal!important}.v18-services{width:330px;min-width:260px;max-width:330px;white-space:normal!important;word-break:normal!important}.v18-services textarea{min-height:110px;resize:vertical}.v18-inactive{opacity:.62;background:#f2f2f2}th{white-space:nowrap}</style>\'\'\';html=html.replace(\'</head>\',css+\'</head>\') if \'</head>\' in html else css+html\n        response.set_data(html);response.headers[\'Content-Length\']=len(response.get_data())\n    return response\n'
